967	+
968	+/* Ma trận 4x4 cột-chính của một nút (matrix hoặc TRS) */
969	+function nodeMat(n: any): number[] {
970	+  if (n.matrix) return n.matrix.slice();
971	+  const [x, y, z, w] = n.rotation ?? [0, 0, 0, 1], [sx, sy, sz] = n.scale ?? [1, 1, 1], [tx, ty, tz] = n.translation ?? [0, 0, 0];
972	+  return [
973	+    (1 - 2 * (y * y + z * z)) * sx, (2 * (x * y + z * w)) * sx, (2 * (x * z - y * w)) * sx, 0,
