989	+/* Mọi primitive của mọi nút có lưới: nút, vật liệu, tam giác, hộp bao thế giới */
990	+function prims(j: any): { node: string; mat: string; tris: number; min: Vec; max: Vec; p: any }[] {
991	+  const out: any[] = [], world = worldOf(j);
992	+  j.nodes.forEach((n: any, i: number) => {
993	+    if (n.mesh === undefined) return;
994	+    const W = world(i);
995	+    for (const p of j.meshes[n.mesh].primitives) {
996	+      const a = j.accessors[p.attributes.POSITION];
997	+      const mn = [Infinity, Infinity, Infinity], mx = [-Infinity, -Infinity, -Infinity];
998	+      for (let c = 0; c < 8; c++) {
999	+        const q = apply(W, [c & 1 ? a.max[0] : a.min[0], c & 2 ? a.max[1] : a.min[1], c & 4 ? a.max[2] : a.min[2]]);
1000	+        for (let d = 0; d < 3; d++) { mn[d] = Math.min(mn[d], q[d]); mx[d] = Math.max(mx[d], q[d]); }
1001	+      }
1002	+      out.push({ node: n.name, mat: j.materials[p.material]?.name, tris: j.accessors[p.indices].count / 3, min: mn, max: mx, p });
1003	+    }
1004	+  });
1005	+  return out;
